require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/review_barrier.json
# is ReviewBarrier.satisfied for one required review over every combination of
# its evidence, generated by `lake exe syrus_fixtures review_barrier`. This runs
# the real Workflows::ImmutableReviewHeadBarrier.satisfied_for? with the same
# evidence. The lookups (the tracked HEAD, the review's terminal evidence,
# approval, a no-change reaction, a recorded exhaustion) read Steps, Runs and
# artifacts and are stubbed; how they combine into a pass is what the model is
# about.
RSpec.describe "ReviewBarrier model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/review_barrier.json").read)
  barrier = Workflows::ImmutableReviewHeadBarrier

  let(:step) do
    workflow = Workflow.create!(job: Factories.job_record, trigger_kind: "initial")
    Step.create!(workflow: workflow, kind: "pr_open", position: 5)
  end

  it "covers every combination of one required review's evidence" do
    expect(fixture.fetch("cases").size).to eq(2**5)
  end

  fixture.fetch("cases").each do |example|
    inputs = example.except("satisfied")
    it "#{example.fetch('satisfied') ? 'passes' : 'holds'} with #{inputs.map { |key, value| "#{key}=#{value}" }.join(', ')}" do
      allow(barrier).to receive(:required_snapshots).and_return([ { "step_kind" => "adversarial_review" } ])
      allow(barrier).to receive(:review_work_step?).and_return(false)
      allow(barrier).to receive(:reviewed_head_sha).and_return(example.fetch("tracked_head") ? "a" * 40 : nil)
      allow(barrier).to receive(:terminal_evidence).and_return(instance_double(Step, succeeded?: example.fetch("succeeded")))
      allow(barrier).to receive(:approved_evidence?).and_return(example.fetch("approved"))
      allow(barrier).to receive(:reacted_without_head_change?).and_return(example.fetch("reacted_without_head_change"))
      allow(barrier).to receive(:exhausted_for_head?).and_return(example.fetch("exhausted_for_head"))

      expect(barrier.satisfied_for?(step)).to eq(example.fetch("satisfied"))
    end
  end
end
